-- VFDA VA Quiz App - Weekly summary database changes (office time zone for Sunday-night emails).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after skills-reports.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261118130000_weekly_summary.sql =====

-- Weekly summary (Sunday night): each office's time zone decides when its
-- Sunday is (default US Eastern). Every summary sent is a notifications row
-- (va_id, event weekly:<Sunday date>), so a VA's week is never sent twice.
--
-- Safe to run more than once.

alter table public.offices add column if not exists time_zone text not null default 'America/New_York';

commit;
